336	///     // Call expensive downstream service...
337	///     Ok(bytes::Bytes::from("payload"))
338	/// }).await?;
339	/// ```
340	pub async fn cache_or_compute<B, F, Fut>(
341	    backend: &B,
342	    key: CacheKey,
343	    ttl: Duration,
344	    compute: F,
345	) -> CacheResult<Arc<CachedResponse>>
346	where
347	    B: CacheBackend,
348	    F: FnOnce() -> Fut + Send,
349	    Fut: std::future::Future<Output = CacheResult<CachedResponse>> + Send,
350	{
351	    // First try to hit the cache
352	    if let Some(res) = backend.get(&key).await? {
353	        return Ok(res);
354	    }
355	
356	    // Otherwise run the supplied closure to compute the response
357	    let computed = compute().await?;
358	
359	    // Fire-and-forget; we don't want to block the response path on cache errors
360	    let backend_clone_key = key.clone();
361	    let backend_clone_val = computed.clone();
362	    let backend_clone = backend as *const B;
363	    let ttl_cpy = ttl;
364	    // SAFETY: Backend is `Sync` and lives at least as long as the spawned task.
365	    tokio::spawn(async move {
366	        // Rebuild &B from raw pointer
367	        // (can't move backend into async block due to lifetime).
368	        let backend_ref = unsafe { &*backend_clone };
369	        let _ = backend_ref
370	            .set(backend_clone_key, (*backend_clone_val).clone(), ttl_cpy)
371	            .await;
372	    });
373	
374	    Ok(Arc::new(computed))
375	}
