91	/// GET /api/v1/courses
92	///
93	/// Returns a paginated list of courses, leveraging response caching when
94	/// `page=1`.  Subsequent pages are considered less frequently requested and
95	/// therefore bypass the cache.
96	#[get("/api/v1/courses")]
97	pub async fn list_courses(
98	    state: Data<AppState>,
99	    query: Query<CourseListQuery>,
100	) -> Result<impl Responder, GatewayError> {
101	    // ---------------------------------------------------------------------
102	    // Pagination sanitization
103	    // ---------------------------------------------------------------------
104	    let page = query.page.unwrap_or(1).max(1);
105	    let per_page = query.per_page.unwrap_or(20).clamp(1, 100);
106	
107	    let cache_key = format!("v1::courses::page={page}::per={per_page}");
108	    // We only cache the first page, as it usually contains the most popular
109	    // public catalogue, whereas deeper pages are cold.
110	    if page == 1 {
111	        if let Some(cached) = state.cache.get::<Paged<serde_json::Value>>(&cache_key).await? {
112	            trace!("cache hit for `{cache_key}`");
113	            state.metrics.cache_hits.inc();
114	            return Ok(HttpResponse::Ok().json(cached));
115	        }
116	    }
117	
118	    // ---------------------------------------------------------------------
119	    // Delegate to the service layer
120	    // ---------------------------------------------------------------------
121	    let timer = state.metrics.course_list_latency.start_timer();
122	    let page_data = state
123	        .course_service
124	        .list_courses(page, per_page)
125	        .await
126	        .map_err(|e| {
127	            error!("course_service.list_courses failed: {e}");
128	            GatewayError::from(e)
129	        })?;
130	    timer.observe_duration();
131	
132	    // Fire-and-forget: populate cache without blocking the main request.
133	    if page == 1 {
134	        let cache = state.cache.clone();
135	        tokio::spawn(async move {
136	            // Cache for 60 seconds — tuned via load testing.
137	            let _ = cache
138	                .put(&cache_key, &page_data, Duration::from_secs(60))
139	                .await;
140	        });
141	    }
142	
143	    Ok(HttpResponse::Ok().json(page_data))
144	}
145	
146	/// GET /api/v1/courses/{course_id}
147	///
148	/// Fetches the detail of a single course.  Aggressively cached for short
149	/// periods because course metadata rarely changes.
150	#[get("/api/v1/courses/{course_id}")]
151	pub async fn get_course(
152	    state: Data<AppState>,
153	    course_id: Path<String>,
154	) -> Result<impl Responder, GatewayError> {
155	    let course_id = course_id.into_inner();
156	    let cache_key = format!("v1::course::{course_id}");
157	
158	    if let Some(cached) = state.cache.get::<serde_json::Value>(&cache_key).await? {
159	        trace!("cache hit for `{cache_key}`");
160	        state.metrics.cache_hits.inc();
161	        return Ok(HttpResponse::Ok().json(cached));
162	    }
163	
164	    let timer = state.metrics.course_detail_latency.start_timer();
165	    let course = state
166	        .course_service
167	        .get_course(&course_id)
168	        .await
169	        .map_err(GatewayError::from)?;
170	    timer.observe_duration();
171	
172	    // Cache for 5 minutes
173	    let cache = state.cache.clone();
174	    let key_clone = cache_key.clone();
175	    tokio::spawn(async move {
176	        let _ = cache
177	            .put(&key_clone, &course, Duration::from_secs(300))
178	            .await;
179	    });
180	
181	    Ok(HttpResponse::Ok().json(course))
182	}
183	
184	/// POST /api/v1/courses
185	///
186	/// Creates a new course.  Only authorized instructor tokens may perform this
187	/// operation (auth middleware not shown here).
188	#[post("/api/v1/courses")]
189	pub async fn create_course(
190	    state: Data<AppState>,
191	    payload: Json<NewCourseReq>,
192	) -> Result<impl Responder, GatewayError> {
193	    let new_course = payload.into_inner();
194	    let timer = state.metrics.course_create_latency.start_timer();
195	
196	    let created = state
197	        .course_service
198	        .create_course(new_course.title, new_course.description, new_course.language)
199	        .await
200	        .map_err(GatewayError::from)?;
201	
202	    timer.observe_duration();
203	    // Purge first-page courses cache so the new course appears immediately.
204	    tokio::spawn({
205	        let cache = state.cache.clone();
206	        async move {
207	            let _ = cache.invalidate_pattern("v1::courses::page=1*").await;
208	        }
209	    });
210	
211	    Ok(HttpResponse::Created().json(ApiMessage { data: created }))
212	}
