2	//! models.rs
3	//!
4	//! Central data structures shared across the EduGate Rustica API-gateway.
5	//! –––
6	//! The gateway is intentionally thin: it does not own business domain
7	//! entities; instead, it focuses on request/response envelopes, error
8	//! abstraction, cache metadata, and lightweight monitoring probes.
9	//!
10	//! All structs are `Serialize`/`Deserialize` to allow seamless propagation
11	//! through e.g. a distributed cache or an async message bus.
12	
13	#![allow(clippy::module_name_repetitions)]
14	
15	use std::borrow::Cow;
16	use std::error::Error as StdError;
17	use std::fmt;
18	use std::time::{Duration, SystemTime};
19	
20	use chrono::{DateTime, Utc};
21	use serde::{Deserialize, Serialize};
22	use uuid::Uuid;
23	
24	/// Common `Result` alias used throughout the gateway.
25	pub type GatewayResult<T> = Result<T, GatewayError>;
26	
27	/// Semantic API version recognised by the gateway.
28	///
29	/// The `ApiVersion` is parsed from the `Accept-Version` HTTP header
30	/// (`v=<semver>` style) or extracted from the URL path (`/v{major}`).
31	#[derive(Debug, Clone, Copy, Eq, PartialEq, Hash, Serialize, Deserialize)]
32	#[serde(rename_all = "lowercase")]
33	pub enum ApiVersion {
34	    V1,
35	    V2,
36	}
37	
38	impl fmt::Display for ApiVersion {
39	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
40	        let version_str = match self {
41	            ApiVersion::V1 => "v1",
42	            ApiVersion::V2 => "v2",
43	        };
44	        f.write_str(version_str)
45	    }
46	}
47	
48	/// Pagination helper understood by every collection-returning endpoint.
49	///
50	/// The default `limit` is intentionally low (20) to avoid abuse.
51	#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
52	pub struct Pagination {
53	    #[serde(default = "Pagination::default_limit")]
54	    pub limit: u32,
55	    #[serde(default)]
56	    pub offset: u32,
57	}
58	
59	impl Pagination {
60	    const fn default_limit() -> u32 {
61	        20
62	    }
63	}
64	
65	/// HTTP cache policy specified by an upstream service.
66	///
67	/// The gateway honours the strongest directive (i.e. *NoCache* over any
68	/// *Public*/**Private* variants) when aggregating multiple sub-requests.
69	#[derive(Debug, Clone, Copy, Serialize, Deserialize)]
70	#[serde(tag = "type", content = "ttl_secs", rename_all = "snake_case")]
71	pub enum CachePolicy {
72	    /// Response must never be cached (e.g. tokens, sensitive PII).
73	    NoCache,
74	    /// Cacheable for *public* clients (shared caches, CDN, etc.).
75	    Public(u32),
76	    /// Cacheable but *only* for the individual authenticated user.
77	    Private(u32),
78	}
79	
80	impl CachePolicy {
81	    /// Convert the `CachePolicy` into a concrete `Duration`, if cacheable.
82	    pub fn ttl(&self) -> Option<Duration> {
83	        match self {
84	            CachePolicy::NoCache => None,
85	            CachePolicy::Public(ttl) | CachePolicy::Private(ttl) => {
86	                Some(Duration::from_secs(u64::from(*ttl)))
87	            }
88	        }
89	    }
90	}
91	
92	/// Metadata attached to any cached entry.
93	#[derive(Debug, Clone, Serialize, Deserialize)]
94	pub struct CachedResponseMeta {
95	    pub cached_at: DateTime<Utc>,
96	    pub expires_at: DateTime<Utc>,
97	    pub policy: CachePolicy,
98	}
99	
100	/// A syntactically stable cache key.
101	///
102	/// Keys are generated from the HTTP method, canonicalised path, stable
103	/// query-string order, and the `ApiVersion`.  User-scoped keys append the
104	/// caller's `user_id` to guarantee segregation.
105	#[derive(Debug, Clone, Eq, PartialEq, Hash, Serialize, Deserialize)]
106	pub struct CacheKey(Cow<'static, str>);
107	
108	impl CacheKey {
109	    /// Build a *public* cache key.
110	    pub fn public(method: &str, canonical_path: &str, version: ApiVersion) -> Self {
111	        let raw = format!("{method}:{version}:{canonical_path}");
112	        Self(Cow::Owned(raw))
113	    }
114	
115	    /// Build a *private* (user-scoped) cache key.
116	    pub fn private(
117	        method: &str,
118	        canonical_path: &str,
119	        version: ApiVersion,
120	        user_id: Uuid,
121	    ) -> Self {
122	        let raw = format!("{method}:{version}:{canonical_path}:user:{user_id}");
123	        Self(Cow::Owned(raw))
124	    }
125	
126	    /// Borrow the inner string slice.
127	    pub fn as_str(&self) -> &str {
128	        &self.0
129	    }
130	}
131	
132	/// Envelope around *all* successful JSON responses.
133	///
134	/// ‑ `data`      → requested payload (generic)
135	/// ‑ `version`   → semantic API version
136	/// ‑ `request_id`→ trace-id injected into every log line
137	#[derive(Debug, Clone, Serialize)]
138	pub struct ApiResponse<T>
139	where
140	    T: Serialize,
141	{
142	    pub data: T,
143	    pub version: ApiVersion,
144	    pub request_id: Uuid,
145	}
146	
147	/// Lightweight monitoring probe collected per request.
148	///
149	/// Surface area kept intentionally tiny.  If you need more dimensions,
150	/// push the events into your metrics backend instead of bloating structs.
151	#[derive(Debug, Clone, Serialize, Deserialize)]
152	pub struct Probe {
153	    /// RFC 3339 representation of when the request started processing.
154	    pub started_at: DateTime<Utc>,
155	    /// Nanoseconds elapsed until a response left the gateway.
156	    pub duration_ns: u128,
157	    /// Whether the response came from cache.
158	    pub cache_hit: bool,
159	}
160	
161	/// High-level error categories returned by the gateway.
162	///
163	/// Mapping rules:
164	///  • 400-series → client mistake (4xx)
165	///  • 500-series → gateway/upstream failure (5xx)
166	#[derive(Debug, Clone, Copy, Eq, PartialEq, Hash, Serialize, Deserialize)]
167	#[serde(rename_all = "snake_case")]
168	pub enum ErrorKind {
169	    BadRequest,
170	    Unauthorized,
171	    Forbidden,
172	    NotFound,
173	    Conflict,
174	    Timeout,
175	    UpstreamFailure,
176	    Internal,
177	    ServiceUnavailable,
178	}
179	
180	/// Canonical error-response payload.
181	///
182	/// Every error is *enveloped* in a friendly JSON object.  This allows iOS,
183	/// Android, and web clients to handle failures uniformly.
184	///
185	/// Example:
186	/// ```json
187	/// {
188	///   "error": {
189	///     "kind": "not_found",
190	///     "message": "Course 123 does not exist",
191	///     "request_id": "d0af8d7e-9cf3-4c28-b676-9b9e585ef05a"
192	///   }
193	/// }
194	/// ```
195	#[derive(Debug, Serialize)]
196	pub struct ErrorResponse<'a> {
197	    pub error: GatewayError<'a>,
198	}
199	
200	/// Gateway-internal error type with rich context.
201	#[derive(Debug, Clone, Serialize)]
202	pub struct GatewayError<'a> {
203	    pub kind: ErrorKind,
204	    pub message: Cow<'a, str>,
205	    pub request_id: Uuid,
206	    /// Optional opaque source for server logs (excluded from JSON by default).
207	    #[serde(skip_serializing)]
208	    pub source: Option<String>,
209	}
210	
211	impl<'a> GatewayError<'a> {
212	    /// Create a new user-facing error with no underlying source.
213	    pub fn new(kind: ErrorKind, message: impl Into<Cow<'a, str>>, request_id: Uuid) -> Self {
214	        Self {
215	            kind,
216	            message: message.into(),
217	            request_id,
218	            source: None,
219	        }
220	    }
221	
222	    /// Attach a low-level error for server-side debugging.
223	    pub fn with_source<E>(mut self, err: E) -> Self
224	    where
225	        E: StdError,
226	    {
227	        self.source = Some(err.to_string());
228	        self
229	    }
230	}
231	
232	impl<'a> fmt::Display for GatewayError<'a> {
233	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
234	        write!(
235	            f,
236	            "[{}] {} (request_id = {})",
237	            self.kind as u8, // numeric variant index, stable over builds
238	            self.message,
239	            self.request_id
240	        )
241	    }
242	}
243	
244	impl<'a> StdError for GatewayError<'a> {}
245	
246	/// Convert any error implementing `StdError + Send + Sync + 'static`
247	/// into a generic `Internal` gateway failure retaining the original
248	/// [`Debug`] representation.
249	impl<'a, E> From<(E, Uuid)> for GatewayError<'a>
250	where
251	    E: StdError,
252	{
253	    fn from((err, request_id): (E, Uuid)) -> Self {
254	        GatewayError {
255	            kind: ErrorKind::Internal,
256	            message: Cow::Borrowed("Internal server error"),
257	            request_id,
258	            source: Some(format!("{err:?}")),
259	        }
260	    }
261	}
262	
263	/// Simple stopwatch used to measure latency per request.
264	///
265	/// Dropping the guard automatically assigns `duration_ns` inside [`Probe`].
266	pub struct Stopwatch {
267	    started: SystemTime,
268	}
269	
270	impl Stopwatch {
271	    #[must_use]
272	    pub fn start() -> Self {
273	        Self {
274	            started: SystemTime::now(),
275	        }
276	    }
277	
278	    /// Finish the measurement and produce a `Probe`.
279	    pub fn finish(self, cache_hit: bool) -> Probe {
280	        let duration_ns = self
281	            .started
282	            .elapsed()
283	            .map(|d| d.as_nanos())
284	            .unwrap_or_default();
285	
286	        Probe {
287	            started_at: DateTime::<Utc>::from(self.started),
288	            duration_ns,
289	            cache_hit,
290	        }
291	    }
292	}
