2	//! Service-layer abstraction for EduGate Rustica.
3	//!
4	//! This module hides the details of talking to the downstream micro-services
5	//! (course, assessment, progress, recommendation) behind an ergonomic async
6	//! API.  Each request is automatically
7	//!   • version-pinned,
8	//!   • cached (when configured as cacheable),
9	//!   • traced with `tracing` and `metrics`,
10	//!   • and mapped onto a unified `GatewayError`.
11	//!
12	//! Example
13	//! -------
14	//! ```no_run
15	//! # use edugate_rustica::services::{ServiceLayer, ServiceConfig};
16	//! # #[tokio::main]
17	//! # async fn main() -> anyhow::Result<()> {
18	//! let services = ServiceLayer::new(ServiceConfig::default())?;
19	//! let catalog = services.course_catalog(1, 20).await?;
20	//! println!("Course catalog page 1: {catalog:#?}");
21	//! # Ok(())
22	//! # }
23	//! ```
24	
25	use std::{
26	    collections::HashMap,
27	    sync::Arc,
28	    time::{Duration, Instant},
29	};
30	
31	use lru::LruCache;
32	use parking_lot::Mutex;
33	use reqwest::{Client, StatusCode, Url};
34	use serde::Deserialize;
35	use serde_json::Value;
36	use thiserror::Error;
37	use tokio::time::timeout;
38	use tracing::{debug, error, info, instrument};
39	
40	/// Downstream micro-services we delegate to.
41	///
42	/// The enum is *private*—callers should not need to know which service
43	/// backs which method.
44	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
45	enum Downstream {
46	    Course,
47	    Assessment,
48	    Progress,
49	    Recommendation,
50	}
51	
52	impl Downstream {
53	    /// Human-friendly name for logging/metrics
54	    fn label(self) -> &'static str {
55	        match self {
56	            Downstream::Course => "course",
57	            Downstream::Assessment => "assessment",
58	            Downstream::Progress => "progress",
59	            Downstream::Recommendation => "recommendation",
60	        }
61	    }
62	}
63	
64	/// Per-service base URL + version.
65	#[derive(Clone)]
66	struct Endpoint {
67	    base: Url,
68	    version: String,
69	}
70	
71	impl Endpoint {
72	    fn url(&self, path: &str) -> Result<Url, GatewayError> {
73	        let mut url = self.base.clone();
74	        url.set_path(&format!("{}/{path}", self.version.trim_start_matches('/')));
75	        Ok(url)
76	    }
77	}
