79	/// Configuration knobs for the service layer.
80	///
81	/// In a real deployment most of these would come from env-vars or a
82	/// structured config file, but a struct keeps the example self-contained.
83	#[derive(Clone)]
84	pub struct ServiceConfig {
85	    /// Capacity of the in-memory LRU cache (number of distinct keys).
86	    pub cache_capacity: usize,
87	    /// Default time-to-live for cache entries that do not specify their own.
88	    pub default_ttl: Duration,
89	    /// Maximum duration before an outbound request is cancelled.
