104	    let page = query.page.unwrap_or(1).max(1);
105	    let per_page = query.per_page.unwrap_or(20).clamp(1, 100);
106	
107	    let cache_key = format!("v1::courses::page={page}::per={per_page}");
108	    // We only cache the first page, as it usually contains the most popular
109	    // public catalogue, whereas deeper pages are cold.
110	    if page == 1 {
111	        if let Some(cached) = state.cache.get::<Paged<serde_json::Value>>(&cache_key).await? {
112	            trace!("cache hit for `{cache_key}`");
113	            state.metrics.cache_hits.inc();
114	            return Ok(HttpResponse::Ok().json(cached));
